#!/usr/bin/env bash
#
# 13-brand-assets-indigo.sh
# -------------------------------------------------------------------
# Drops the new Nexum brand assets (flow-N mark, indigo+cyan) into
# public/brand/, swaps the favicon, and updates the logo component to
# render the new mark. Self-contained: PNGs are embedded, no downloads.
#
# Run AFTER 12-rebrand-indigo-cyan.sh (colors), or alongside it.
# Safe to re-run. Writes a timestamped backup; --revert restores it.
# -------------------------------------------------------------------
set -euo pipefail

if   [ -f "./tailwind.config.ts" ] && [ -d "./app" ]; then WEB="."
elif [ -d "./nexum-web" ];                             then WEB="./nexum-web"
elif [ -d "./Nexum-main/nexum-web" ];                  then WEB="./Nexum-main/nexum-web"
else echo "ERROR: run from nexum-web or its parent (couldn't find tailwind.config.ts)." >&2; exit 1; fi
cd "$WEB"
echo "==> Working in: $(pwd)"

BACKUP=".brand-backup"
FILES=("public/favicon.svg" "public/brand/og-image.png" "components/brand/AfriFXLogo.tsx")

if [ "${1:-}" = "--revert" ]; then
  latest=$(ls -1dt "$BACKUP"/* 2>/dev/null | head -n1 || true)
  [ -z "$latest" ] && { echo "No backup found."; exit 1; }
  echo "==> Reverting from $latest"
  for f in "${FILES[@]}"; do [ -f "$latest/$f" ] && mkdir -p "$(dirname "$f")" && cp "$latest/$f" "$f" && echo "   restored $f"; done
  echo "==> Revert complete."; exit 0
fi

STAMP=$(date +%Y%m%d-%H%M%S); DEST="$BACKUP/$STAMP"; mkdir -p "$DEST"
for f in "${FILES[@]}"; do [ -f "$f" ] && { mkdir -p "$DEST/$(dirname "$f")"; cp "$f" "$DEST/$f"; }; done
echo "==> Backup written to $DEST"

mkdir -p public/brand

cat > public/favicon.svg << 'FAVEOF'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none">
  <rect width="32" height="32" rx="8" fill="#0B1020"/>
  <defs>
    <linearGradient id="fg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#5FE3EC"/>
      <stop offset="1" stop-color="#2E8CE0"/>
    </linearGradient>
  </defs>
  <path d="M9 23 L9 9 L23 23 L23 9" fill="none" stroke="url(#fg)" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/>
</svg>
FAVEOF
echo "   favicon.svg          -> flow-N mark"

cat > public/brand/nexum-mark.svg << 'MARKEOF'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120" fill="none">
  <defs>
    <linearGradient id="nx-mark-g" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#5FE3EC"/>
      <stop offset="1" stop-color="#2E8CE0"/>
    </linearGradient>
  </defs>
  <path d="M34 92 L34 30 L86 92 L86 30" fill="none" stroke="url(#nx-mark-g)" stroke-width="11" stroke-linecap="round" stroke-linejoin="round"/>
</svg>
MARKEOF
echo "   brand/nexum-mark.svg -> written"

cat > public/brand/hero-bg.svg << 'HEROEOF'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 720" fill="none" preserveAspectRatio="xMidYMid slice">
  <defs>
    <radialGradient id="glow" cx="30%" cy="20%" r="80%">
      <stop offset="0" stop-color="#13234A"/>
      <stop offset="55%" stop-color="#0B1020"/>
      <stop offset="100%" stop-color="#080C18"/>
    </radialGradient>
  </defs>
  <rect width="1440" height="720" fill="url(#glow)"/>
  <g stroke="#26314F" stroke-width="1.2" opacity="0.5">
    <line x1="140" y1="140" x2="360" y2="90"/>
    <line x1="360" y1="90" x2="520" y2="260"/>
    <line x1="140" y1="140" x2="240" y2="360"/>
    <line x1="520" y1="260" x2="240" y2="360"/>
    <line x1="1040" y1="120" x2="1240" y2="200"/>
    <line x1="1240" y1="200" x2="1180" y2="420"/>
    <line x1="1040" y1="120" x2="1180" y2="420"/>
    <line x1="900" y1="560" x2="1100" y2="620"/>
    <line x1="1100" y1="620" x2="1180" y2="420"/>
  </g>
  <g fill="#3DD6E0" opacity="0.45">
    <circle cx="140" cy="140" r="4"/><circle cx="360" cy="90" r="4"/><circle cx="520" cy="260" r="4"/><circle cx="240" cy="360" r="4"/>
    <circle cx="1040" cy="120" r="4"/><circle cx="1240" cy="200" r="4"/><circle cx="1180" cy="420" r="4"/><circle cx="900" cy="560" r="4"/><circle cx="1100" cy="620" r="4"/>
  </g>
</svg>
HEROEOF
echo "   brand/hero-bg.svg    -> written"

base64 -d > public/brand/og-image.png << 'OGEOF'
