echo "   brand/hero-bg.png    -> 1440x720 hero"

python3 - << 'PYEOF'
p = "components/brand/AfriFXLogo.tsx"
s = open(p).read()
s = s.replace("showMark = false, // NEXUM: hexagon mark dropped pending new design",
              "showMark = true, // NEXUM: flow-N mark (indigo+cyan)")
start = s.find("<svg width={dims.mark}")
end   = s.find("</svg>", start)
if start != -1 and end != -1:
    end += len("</svg>")
    new_svg = (
        '<svg width={dims.mark} height={dims.mark} viewBox="0 0 120 120" fill="none" className="shrink-0">\n'
        '          <defs>\n'
        '            <linearGradient id="nx-mark-g" x1="0" y1="0" x2="1" y2="1">\n'
        '              <stop offset="0" stopColor="#5FE3EC" />\n'
        '              <stop offset="1" stopColor="#2E8CE0" />\n'
        '            </linearGradient>\n'
        '          </defs>\n'
        '          <path d="M34 92 L34 30 L86 92 L86 30" fill="none" stroke="url(#nx-mark-g)" strokeWidth="11" strokeLinecap="round" strokeLinejoin="round" />\n'
        '        </svg>'
    )
    s = s[:start] + new_svg + s[end:]
    open(p,"w").write(s)
    print("   AfriFXLogo.tsx       -> flow-N mark enabled")
else:
    print("   WARN: could not find mark <svg> block; logo component left unchanged")
PYEOF

echo ""
echo "==> Brand assets installed. Review with: git diff --stat"
if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  git --no-pager diff --stat 2>/dev/null || true
fi
echo ""
echo "==> Next (build locally, then deploy to production — you run these):"
echo "    rm -rf .next && npx tsc --noEmit && npm run build"
echo "    git add -A && git commit -m 'brand: flow-N mark + indigo OG/hero assets' && git push"
